// Extended template library (Polish, house style of the built-in templates)
export default [
  { "id": "xr_chest_pa_lateral", "title": "RTG Chest PA + lateral", "group": "Non-trauma", "section": "Chest / Thorax", "priority": 20,
    "text": "Badanie: RTG klatki piersiowej w projekcji PA i bocznej\n\nOpis:\nPłuca bez zmian ogniskowych i bez zagęszczeń miąższowych.\nRysunek naczyniowy płuc prawidłowy.\nWnęki płucne prawidłowe.\nBez cech odmy opłucnowej. Kąty przeponowo-żebrowe wolne, w tym tylne kąty w projekcji bocznej.\nPrzestrzeń zamostkowa i przestrzeń zasercowa prawidłowo przejrzyste.\n\nSylwetka serca niepowiększona. Śródpiersie nieposzerzone, tchawica w linii pośrodkowej.\nKopuły przepony gładkie, prawidłowo położone.\n\nW uwidocznionym zakresie układ kostny bez istotnych zmian.\n\nWnioski:\n- Obraz RTG klatki piersiowej bez istotnych odchyleń od normy." },
  { "id": "xr_chest_insp_exp", "title": "RTG Chest inspiratory + expiratory", "group": "Non-trauma", "section": "Chest / Thorax", "priority": 21,
    "text": "Badanie: RTG klatki piersiowej w projekcji PA na wdechu i na wydechu\n\nOpis:\nPłuca prawidłowo powietrzne, bez zmian ogniskowych i bez zagęszczeń miąższowych.\nNa zdjęciu wydechowym nie uwidoczniono linii opłucnej trzewnej ani obszarów pozbawionych rysunku płucnego.\nBez cech odmy opłucnowej.\nSymetryczne zmniejszenie objętości obu płuc na wydechu, bez cech pułapki powietrznej.\nKąty przeponowo-żebrowe wolne.\n\nSylwetka serca niepowiększona. Śródpiersie nieposzerzone, w linii pośrodkowej w obu fazach oddechowych.\nKopuły przepony gładkie, symetrycznie ruchome.\n\nW uwidocznionym zakresie układ kostny bez istotnych zmian.\n\nWnioski:\n- Bez cech odmy opłucnowej.\n- Bez cech pułapki powietrznej." },
  { "id": "xr_chest_postop_drain", "title": "RTG Chest post-op / drain control", "group": "Non-trauma", "section": "Chest / Thorax", "priority": 22,
    "text": "Badanie: RTG klatki piersiowej – kontrola pooperacyjna / kontrola drenażu\n\nOpis:\nDren opłucnowy wprowadzony po stronie …, z końcem w rzucie … pola płucnego.\nBoczne otwory drenu w obrębie jamy opłucnowej.\n\nPłuco … rozprężone, bez cech odmy opłucnowej.\nBez płynu w jamach opłucnowych. Kąty przeponowo-żebrowe wolne.\nPłuca bez ognisk zagęszczeń miąższowych. Bez cech zastoju w krążeniu płucnym.\nBez cech rozedmy podskórnej.\n\nSylwetka serca niepowiększona. Śródpiersie nieposzerzone, w linii pośrodkowej.\n\nWnioski:\n- Dren opłucnowy po stronie … w prawidłowym położeniu.\n- Płuco … rozprężone, bez cech odmy opłucnowej." },
  { "id": "xr_chest_post_cvc", "title": "RTG Chest after central line insertion", "group": "Non-trauma", "section": "Chest / Thorax", "priority": 23,
    "text": "Badanie: RTG klatki piersiowej po założeniu cewnika do żyły centralnej\n\nOpis:\nCewnik żyły centralnej wprowadzony przez żyłę … …, o prawidłowym przebiegu, bez zagięć i pętli.\nKoniec cewnika w rzucie dolnej części żyły głównej górnej.\n\nBez cech odmy opłucnowej.\nBez płynu w jamach opłucnowych. Kąty przeponowo-żebrowe wolne.\nPłuca bez ognisk zagęszczeń miąższowych.\nŚródpiersie nieposzerzone. Sylwetka serca niepowiększona.\n\nWnioski:\n- Cewnik żyły centralnej w prawidłowym położeniu, z końcem w rzucie żyły głównej górnej.\n- Bez cech odmy opłucnowej." },
  { "id": "xr_chest_newborn", "title": "RTG Chest newborn", "group": "Non-trauma", "section": "Paediatric", "priority": 20,
    "text": "Badanie: RTG klatki piersiowej noworodka w projekcji AP\n\nOpis:\nPłuca prawidłowo i symetrycznie powietrzne, bez zagęszczeń miąższowych.\nBez obrazu siateczkowo-ziarnistego i bez bronchogramu powietrznego.\nBez płynu w szczelinach międzypłatowych.\nBez cech odmy opłucnowej i odmy śródpiersiowej.\nKąty przeponowo-żebrowe wolne.\n\nSylwetka serca i śródpiersie w granicach normy dla wieku.\nKopuły przepony prawidłowo położone.\nPęcherz gazu żołądka pod lewą kopułą przepony.\n\nW uwidocznionym zakresie układ kostny bez istotnych zmian.\n\nWnioski:\n- Obraz RTG klatki piersiowej noworodka bez istotnych odchyleń od normy." },
  { "id": "xr_chest_fb_child", "title": "RTG Chest child foreign body (insp/exp)", "group": "Non-trauma", "section": "Paediatric", "priority": 21,
    "text": "Badanie: RTG klatki piersiowej u dziecka na wdechu i na wydechu – w kierunku aspiracji ciała obcego\n\nOpis:\nNie uwidoczniono cieniującego ciała obcego w rzucie dróg oddechowych ani przełyku.\nPłuca symetrycznie powietrzne na wdechu.\nNa zdjęciu wydechowym symetryczne zmniejszenie powietrzności obu płuc, bez cech pułapki powietrznej.\nŚródpiersie w linii pośrodkowej w obu fazach oddechowych.\nBez zagęszczeń miąższowych i bez niedodmy.\nBez cech odmy opłucnowej. Kąty przeponowo-żebrowe wolne.\n\nSylwetka serca i śródpiersie w granicach normy dla wieku.\n\nWnioski:\n- Bez radiologicznych cech aspiracji ciała obcego.\n- Prawidłowy obraz RTG nie wyklucza aspiracji niecieniującego ciała obcego; przy utrzymującym się podejrzeniu klinicznym do rozważenia bronchoskopia." },
  { "id": "xr_abdomen_left_decubitus", "title": "RTG Abdomen left lateral decubitus", "group": "Non-trauma", "section": "Abdomen / Pelvis", "priority": 20,
    "text": "Badanie: RTG przeglądowe jamy brzusznej w pozycji leżącej na lewym boku, promieniem poziomym\n\nOpis:\nBadanie wykonano w trybie ostrodyżurowym.\n\nPomiędzy wątrobą a prawą boczną ścianą jamy brzusznej nie uwidoczniono wolnego powietrza.\nPrawidłowy rozkład gazów w jelitach. Pętle jelita cienkiego i grubego nieposzerzone.\nBez patologicznych poziomów płynów w pętlach jelitowych.\n\nWnioski:\n- Bez radiologicznych cech wolnego powietrza w jamie otrzewnej.\n- Bez radiologicznych cech niedrożności jelit." },
  { "id": "xr_kub", "title": "RTG KUB (urinary tract)", "group": "Non-trauma", "section": "Abdomen / Pelvis", "priority": 21,
    "text": "Badanie: RTG przeglądowe jamy brzusznej – układ moczowy (nerki, moczowody, pęcherz moczowy)\n\nOpis:\nNie uwidoczniono cieni złogów w rzucie nerek, przebiegu moczowodów ani pęcherza moczowego.\nZarysy mięśni lędźwiowych symetryczne.\nRozkład gazów w jelitach prawidłowy.\n\nW uwidocznionym zakresie układ kostny bez istotnych zmian.\n\nWnioski:\n- Nie uwidoczniono cieniujących złogów w rzucie układu moczowego.\n- Prawidłowy obraz RTG nie wyklucza złogów niecieniujących lub drobnych; do rozważenia USG lub TK bez kontrastu." },
  { "id": "xr_ng_tube_position", "title": "RTG NG / feeding tube position", "group": "Non-trauma", "section": "Abdomen / Pelvis", "priority": 22,
    "text": "Badanie: RTG klatki piersiowej i nadbrzusza – kontrola położenia zgłębnika\n\nOpis:\nZgłębnik przebiega w linii pośrodkowej, w osi przełyku, bez odchylenia do oskrzeli głównych na poziomie ostrogi tchawicy.\nZgłębnik przechodzi przez przeponę w linii pośrodkowej.\nKoniec zgłębnika w rzucie żołądka, ok. … cm poniżej lewej kopuły przepony.\nBez cech zapętlenia zgłębnika.\n\nW uwidocznionym zakresie bez cech odmy opłucnowej.\n\nWnioski:\n- Zgłębnik w prawidłowym położeniu, z końcem w rzucie żołądka." },
  { "id": "xr_abdomen_newborn", "title": "RTG Abdomen newborn (NEC)", "group": "Non-trauma", "section": "Paediatric", "priority": 22,
    "text": "Badanie: RTG jamy brzusznej noworodka w projekcji AP i bocznej promieniem poziomym\n\nOpis:\nPrawidłowy, równomierny rozkład gazów w jelitach. Pętle jelitowe nieposzerzone.\nGaz obecny w odbytnicy.\nNie uwidoczniono gazu w ścianach jelit (bez cech pneumatozy jelit).\nBez gazu w układzie żyły wrotnej.\nNie uwidoczniono wolnego powietrza w jamie otrzewnej.\n\nW uwidocznionym zakresie płuca bez zagęszczeń. Układ kostny bez istotnych zmian.\n\nWnioski:\n- Bez radiologicznych cech martwiczego zapalenia jelit (NEC).\n- Bez cech wolnego powietrza w jamie otrzewnej." },
  { "id": "xr_fb_ingested_child", "title": "RTG Swallowed foreign body child", "group": "Non-trauma", "section": "Paediatric", "priority": 23,
    "text": "Badanie: RTG szyi, klatki piersiowej i jamy brzusznej u dziecka – w kierunku połkniętego ciała obcego\n\nOpis:\nNie uwidoczniono cieniującego ciała obcego w rzucie gardła, przełyku, żołądka ani jelit.\nPrawidłowy rozkład gazów w jelitach. Pętle jelitowe nieposzerzone.\n\nPłuca bez zagęszczeń miąższowych. Bez cech odmy opłucnowej.\nTkanki miękkie przedkręgowe szyi nieposzerzone.\n\nW uwidocznionym zakresie układ kostny bez istotnych zmian.\n\nWnioski:\n- Nie uwidoczniono cieniującego ciała obcego.\n- Prawidłowy obraz RTG nie wyklucza obecności niecieniującego ciała obcego." },
  { "id": "fl_barium_swallow", "title": "RTG Barium swallow", "group": "Non-trauma", "section": "Abdomen / Pelvis", "priority": 30,
    "text": "Badanie: RTG przełyku z kontrastem\n\nOpis:\nBadanie wykonano pod kontrolą fluoroskopii, po doustnym podaniu barytowego środka kontrastowego, w projekcjach AP, skośnych i bocznej.\n\nFaza gardłowa połykania prawidłowa, bez zalegania środka kontrastowego w dolinkach nagłośniowych i zachyłkach gruszkowatych.\nBez aspiracji środka kontrastowego do dróg oddechowych.\nPrzełyk prawidłowej szerokości, o gładkich zarysach, z prawidłowym rysunkiem fałdów błony śluzowej.\nPerystaltyka prawidłowa, pasaż środka kontrastowego przez przełyk swobodny.\nNie uwidoczniono zwężeń, ubytków wypełnienia, uchyłków ani owrzodzeń.\nWpust prawidłowo położony, swobodnie przechodzi środek kontrastowy do żołądka.\nBez cech przepukliny rozworu przełykowego przepony. W trakcie badania nie uwidoczniono refluksu żołądkowo-przełykowego.\n\nWnioski:\n- Obraz RTG przełyku z kontrastem bez istotnych odchyleń od normy." },
  { "id": "fl_swallow_postop_leak", "title": "RTG Contrast swallow post-op (leak)", "group": "Non-trauma", "section": "Abdomen / Pelvis", "priority": 31,
    "text": "Badanie: RTG przełyku z wodnym środkiem kontrastowym – kontrola po operacji\n\nOpis:\nBadanie wykonano pod kontrolą fluoroskopii, po doustnym podaniu wodnego (jodowego) środka kontrastowego, w projekcjach AP, skośnych i bocznej.\n\nStan po operacji … .\nŚrodek kontrastowy przechodzi swobodnie przez przełyk i okolicę zespolenia … .\nNie uwidoczniono wycieku środka kontrastowego poza światło przewodu pokarmowego ani przetoki.\nOkolica zespolenia bez istotnego zwężenia.\nPasaż środka kontrastowego do … swobodny.\nBez aspiracji środka kontrastowego do dróg oddechowych.\n\nWnioski:\n- Bez radiologicznych cech nieszczelności zespolenia.\n- Badanie nie wyklucza niewielkiej nieszczelności; przy utrzymującym się podejrzeniu klinicznym do rozważenia TK z doustnym środkiem kontrastowym." },
  { "id": "fl_upper_gi", "title": "RTG Upper GI series", "group": "Non-trauma", "section": "Abdomen / Pelvis", "priority": 32,
    "text": "Badanie: RTG górnego odcinka przewodu pokarmowego z kontrastem (przełyk, żołądek, dwunastnica)\n\nOpis:\nBadanie wykonano pod kontrolą fluoroskopii, po doustnym podaniu barytowego środka kontrastowego i środka gazotwórczego (technika podwójnego kontrastu).\n\nPrzełyk prawidłowej szerokości, o gładkich zarysach, pasaż swobodny.\nWpust prawidłowo położony, bez cech przepukliny rozworu przełykowego przepony.\nŻołądek prawidłowego kształtu, wielkości i położenia, o gładkich zarysach, z prawidłowym rysunkiem fałdów błony śluzowej.\nNie uwidoczniono ubytków wypełnienia ani nisz wrzodowych.\nOdźwiernik drożny, opróżnianie żołądka prawidłowe.\nOpuszka dwunastnicy prawidłowo wypełniona, niezniekształcona, bez niszy wrzodowej.\nPętla dwunastnicy o prawidłowym przebiegu. Zgięcie dwunastniczo-czcze prawidłowo położone, po lewej stronie kręgosłupa.\n\nWnioski:\n- Obraz RTG górnego odcinka przewodu pokarmowego bez istotnych odchyleń od normy." },
  { "id": "fl_small_bowel_follow_through", "title": "RTG Small bowel follow-through", "group": "Non-trauma", "section": "Abdomen / Pelvis", "priority": 33,
    "text": "Badanie: RTG pasażu jelita cienkiego z kontrastem\n\nOpis:\nBadanie wykonano po doustnym podaniu barytowego środka kontrastowego; zdjęcia wykonywano w odstępach czasowych, z uciskiem celowanym okolicy krętniczo-kątniczej.\n\nPasaż środka kontrastowego przez jelito cienkie prawidłowy; środek kontrastowy osiągnął kątnicę po … min.\nPętle jelita czczego i krętego prawidłowo rozmieszczone, nieposzerzone, o prawidłowym rysunku fałdów błony śluzowej.\nNie uwidoczniono zwężeń, ubytków wypełnienia ani przetok.\nKońcowy odcinek jelita krętego prawidłowej szerokości, o gładkich zarysach.\nOkolica zastawki krętniczo-kątniczej bez zmian.\n\nWnioski:\n- Obraz RTG pasażu jelita cienkiego bez istotnych odchyleń od normy." },
  { "id": "fl_contrast_enema", "title": "RTG Contrast enema (double contrast)", "group": "Non-trauma", "section": "Abdomen / Pelvis", "priority": 34,
    "text": "Badanie: RTG jelita grubego z kontrastem (wlew doodbytniczy, technika podwójnego kontrastu)\n\nOpis:\nBadanie wykonano po przygotowaniu jelita; przez odbyt podano barytowy środek kontrastowy oraz powietrze, pod kontrolą fluoroskopii.\n\nŚrodek kontrastowy wypełnił całe jelito grube do kątnicy, z zarzuceniem do końcowego odcinka jelita krętego.\nOdbytnica, esica, okrężnica zstępująca, poprzeczna i wstępująca oraz kątnica prawidłowego położenia i szerokości, o gładkich zarysach, z prawidłowym haustrowaniem.\nNie uwidoczniono ubytków wypełnienia, zwężeń ani uchyłków.\nWyrostek robaczkowy … .\n\nWnioski:\n- Obraz RTG jelita grubego z kontrastem bez istotnych odchyleń od normy." },
  { "id": "fl_enema_anastomosis", "title": "RTG Contrast enema anastomosis (leak)", "group": "Non-trauma", "section": "Abdomen / Pelvis", "priority": 35,
    "text": "Badanie: RTG jelita grubego z wodnym środkiem kontrastowym – ocena zespolenia\n\nOpis:\nBadanie wykonano pod kontrolą fluoroskopii; przez odbyt podano wodny (jodowy) środek kontrastowy.\n\nStan po operacji … .\nŚrodek kontrastowy wypełnia odbytnicę i okolicę zespolenia …, przechodzi swobodnie proksymalnie do … .\nNie uwidoczniono wycieku środka kontrastowego poza światło jelita ani przetoki.\nOkolica zespolenia bez istotnego zwężenia.\n\nWnioski:\n- Bez radiologicznych cech nieszczelności ani zwężenia zespolenia jelitowego." },
  { "id": "fl_contrast_enema_child", "title": "RTG Contrast enema child", "group": "Non-trauma", "section": "Paediatric", "priority": 30,
    "text": "Badanie: RTG jelita grubego z kontrastem u dziecka (wlew doodbytniczy)\n\nOpis:\nBadanie wykonano pod kontrolą fluoroskopii; przez cewnik doodbytniczy podano wodny środek kontrastowy.\n\nOdbytnica prawidłowej szerokości, szersza od esicy – wskaźnik odbytniczo-esiczy prawidłowy.\nNie uwidoczniono strefy przejściowej.\nEsica i okrężnica prawidłowej szerokości, o gładkich zarysach.\nŚrodek kontrastowy wypełnił całe jelito grube do kątnicy, położonej typowo w prawym dole biodrowym.\nNie uwidoczniono ubytków wypełnienia ani zwężeń.\n\nWnioski:\n- Obraz RTG jelita grubego z kontrastem bez istotnych odchyleń od normy.\n- Prawidłowy obraz nie wyklucza choroby Hirschsprunga z krótkim odcinkiem bezzwojowym; w razie utrzymującego się podejrzenia klinicznego do rozważenia biopsja ssąca odbytnicy." },
  { "id": "fl_intussusception_reduction", "title": "RTG Intussusception reduction (air enema)", "group": "Non-trauma", "section": "Paediatric", "priority": 31,
    "text": "Badanie: Odprowadzenie wgłobienia jelitowego wlewem doodbytniczym pod kontrolą fluoroskopii\n\nOpis:\nPrzez cewnik doodbytniczy podawano powietrze pod kontrolowanym ciśnieniem (maks. … mmHg), pod kontrolą fluoroskopii.\n\nUwidoczniono głowę wgłobienia w rzucie … .\nGłowa wgłobienia ulegała stopniowemu przesuwaniu w kierunku kątnicy i została całkowicie odprowadzona.\nUzyskano swobodny przepływ powietrza do pętli jelita krętego, co potwierdza całkowite odprowadzenie wgłobienia.\nNie uwidoczniono wolnego powietrza w jamie otrzewnej.\n\nWnioski:\n- Skuteczne, całkowite odprowadzenie wgłobienia jelitowego.\n- Bez cech perforacji.\n- Zalecana obserwacja kliniczna; w razie nawrotu objawów kontrolne USG." },
  { "id": "fl_retrograde_urethrography", "title": "RTG Retrograde urethrography (trauma)", "group": "Trauma", "section": "Abdomen / Pelvis", "priority": 30,
    "text": "Badanie: Uretrografia wsteczna\n\nOpis:\nPo wprowadzeniu cewnika do dołu łódkowatego podano wstecznie wodny środek kontrastowy pod kontrolą fluoroskopii, w projekcji skośnej.\n\nCewka moczowa przednia (część gąbczasta) i tylna (część błoniasta i sterczowa) prawidłowo wypełnione, o gładkich zarysach i prawidłowej szerokości.\nNie uwidoczniono wycieku środka kontrastowego poza światło cewki moczowej.\nBez cech zwężenia cewki moczowej.\nŚrodek kontrastowy przechodzi swobodnie do pęcherza moczowego.\n\nWnioski:\n- Bez radiologicznych cech uszkodzenia cewki moczowej." },
  { "id": "fl_cystography_trauma", "title": "RTG Cystography trauma", "group": "Trauma", "section": "Abdomen / Pelvis", "priority": 31,
    "text": "Badanie: Cystografia wsteczna – uraz\n\nOpis:\nPrzez cewnik w pęcherzu moczowym podano grawitacyjnie wodny środek kontrastowy (… ml) do pełnego wypełnienia pęcherza; zdjęcia wykonano w projekcji AP, w projekcjach skośnych oraz po opróżnieniu pęcherza.\n\nPęcherz moczowy dobrze wypełniony, prawidłowego kształtu, o gładkich zarysach.\nNie uwidoczniono wycieku środka kontrastowego do przestrzeni pozaotrzewnowej ani do jamy otrzewnej, również na zdjęciu po opróżnieniu pęcherza.\n\nWnioski:\n- Bez radiologicznych cech pęknięcia pęcherza moczowego." },
  { "id": "fl_cystography", "title": "RTG Cystography (post-op leak)", "group": "Non-trauma", "section": "Abdomen / Pelvis", "priority": 36,
    "text": "Badanie: Cystografia – ocena szczelności pęcherza moczowego po operacji\n\nOpis:\nPrzez cewnik w pęcherzu moczowym podano wodny środek kontrastowy (… ml) pod kontrolą fluoroskopii; zdjęcia wykonano w projekcji AP, w projekcjach skośnych oraz po opróżnieniu pęcherza.\n\nStan po operacji … .\nPęcherz moczowy dobrze wypełniony, prawidłowego kształtu, o gładkich zarysach.\nNie uwidoczniono wycieku środka kontrastowego w okolicy zespolenia ani w innych odcinkach ściany pęcherza.\nBez cech odpływu pęcherzowo-moczowodowego.\n\nWnioski:\n- Bez radiologicznych cech nieszczelności pęcherza moczowego i zespolenia." },
  { "id": "fl_vcug_child", "title": "RTG VCUG child (MCUG)", "group": "Non-trauma", "section": "Paediatric", "priority": 32,
    "text": "Badanie: Cystouretrografia mikcyjna\n\nOpis:\nPrzez cewnik w pęcherzu moczowym podano wodny środek kontrastowy pod kontrolą fluoroskopii; zdjęcia wykonano w fazie wypełniania, w trakcie mikcji i po mikcji.\n\nPęcherz moczowy prawidłowego kształtu, o gładkich zarysach, bez uchyłków.\nNie uwidoczniono odpływu pęcherzowo-moczowodowego w fazie wypełniania ani w trakcie mikcji.\nCewka moczowa w trakcie mikcji prawidłowej szerokości, o gładkich zarysach, bez cech zwężenia.\nU chłopca bez cech zastawki cewki tylnej.\nPo mikcji bez istotnego zalegania środka kontrastowego w pęcherzu.\n\nWnioski:\n- Bez cech odpływu pęcherzowo-moczowodowego.\n- Prawidłowy obraz pęcherza moczowego i cewki moczowej." },
  { "id": "fl_ivu", "title": "RTG IVU (urografia)", "group": "Non-trauma", "section": "Abdomen / Pelvis", "priority": 37,
    "text": "Badanie: Urografia – RTG układu moczowego po dożylnym podaniu środka kontrastowego\n\nOpis:\nWykonano zdjęcie przeglądowe, a następnie zdjęcia po dożylnym podaniu jodowego środka kontrastowego.\n\nNa zdjęciu przeglądowym nie uwidoczniono cieni złogów w rzucie układu moczowego.\nNerki prawidłowo położone, prawidłowej wielkości, o gładkich zarysach.\nWydzielanie środka kontrastowego przez nerki obustronnie symetryczne, w czasie prawidłowym.\nUkłady kielichowo-miedniczkowe nieposzerzone. Kielichy prawidłowego, czarkowatego kształtu.\nMoczowody o prawidłowym przebiegu i szerokości, bez ubytków wypełnienia.\nPęcherz moczowy o gładkich zarysach, bez ubytków wypełnienia. Po mikcji bez istotnego zalegania.\n\nWnioski:\n- Obraz urograficzny bez istotnych odchyleń od normy." },
  { "id": "fl_hsg", "title": "RTG Hysterosalpingography (HSG)", "group": "Non-trauma", "section": "Abdomen / Pelvis", "priority": 38,
    "text": "Badanie: Histerosalpingografia (HSG)\n\nOpis:\nPo założeniu cewnika do kanału szyjki macicy podano jodowy środek kontrastowy pod kontrolą fluoroskopii.\n\nKanał szyjki macicy prawidłowo wypełniony.\nJama macicy prawidłowego, trójkątnego kształtu, o gładkich zarysach, bez ubytków wypełnienia.\nJajowody obustronnie wypełniają się na całej długości, są prawidłowej szerokości.\nSwobodny wypływ środka kontrastowego do jamy otrzewnej z obu jajowodów, z jego rozproszeniem między pętlami jelitowymi.\n\nWnioski:\n- Prawidłowy obraz jamy macicy.\n- Jajowody obustronnie drożne." },
  { "id": "fl_fistulography", "title": "RTG Fistulography", "group": "Non-trauma", "section": "Combined", "priority": 30,
    "text": "Badanie: Fistulografia\n\nOpis:\nPrzez ujście zewnętrzne przetoki w okolicy … wprowadzono cewnik i podano wodny środek kontrastowy pod kontrolą fluoroskopii.\n\nŚrodek kontrastowy wypełnia kanał przetoki o długości ok. … mm, przebiegający … .\nKanał przetoki ślepo zakończony w tkankach miękkich.\nNie uwidoczniono połączenia kanału z przewodem pokarmowym, pęcherzem moczowym ani z jamą ropnia.\nNie uwidoczniono rozgałęzień kanału.\n\nWnioski:\n- Ślepo zakończony kanał przetoki w tkankach miękkich okolicy …, bez połączenia z narządami wewnętrznymi." },
  { "id": "fl_t_tube_cholangiography", "title": "RTG T-tube cholangiography", "group": "Non-trauma", "section": "Abdomen / Pelvis", "priority": 39,
    "text": "Badanie: Cholangiografia przez dren Kehra\n\nOpis:\nPrzez dren Kehra podano wodny środek kontrastowy pod kontrolą fluoroskopii.\n\nDren Kehra prawidłowo położony w przewodzie żółciowym wspólnym.\nDrogi żółciowe wewnątrz- i zewnątrzwątrobowe prawidłowo wypełnione, nieposzerzone, o gładkich zarysach.\nNie uwidoczniono ubytków wypełnienia w drogach żółciowych.\nSwobodny pasaż środka kontrastowego do dwunastnicy.\nNie uwidoczniono wycieku środka kontrastowego poza drogi żółciowe.\n\nWnioski:\n- Drogi żółciowe drożne, bez cech złogów resztkowych.\n- Bez cech wycieku żółci." },
  { "id": "xr_skull", "title": "RTG Skull", "group": "Trauma", "section": "CT Head", "priority": 20,
    "text": "Badanie: RTG czaszki w projekcjach PA i bocznej\n\nOpis:\nNie uwidoczniono linii złamań kości sklepienia czaszki.\nBez cech wgłobienia odłamów kostnych.\nStruktura kostna sklepienia czaszki prawidłowa, bez zmian ogniskowych.\nSiodło tureckie prawidłowego kształtu i wielkości.\nUwidocznione zatoki przynosowe powietrzne, bez poziomów płynu.\n\nWnioski:\n- Bez radiologicznych cech złamania kości sklepienia czaszki.\n- Prawidłowy obraz RTG nie wyklucza urazu wewnątrzczaszkowego; przy wskazaniach klinicznych do rozważenia TK głowy." },
  { "id": "xr_facial_bones", "title": "RTG Facial bones (OM)", "group": "Trauma", "section": "Facial bones", "priority": 20,
    "text": "Badanie: RTG kości twarzoczaszki w projekcji potyliczno-bródkowej\n\nOpis:\nZarysy oczodołów symetryczne, brzegi dolne i boczne oczodołów ciągłe.\nKości jarzmowe i łuki jarzmowe bez cech złamania.\nŚciany zatok szczękowych ciągłe. Zatoki szczękowe powietrzne, bez poziomów płynu.\nSzwy jarzmowo-czołowe symetryczne, nieposzerzone.\nNie uwidoczniono powietrza w oczodołach.\nTkanki miękkie twarzy bez istotnych zmian.\n\nWnioski:\n- Bez radiologicznych cech złamania kości twarzoczaszki.\n- Przy utrzymującym się podejrzeniu klinicznym złamania do rozważenia TK twarzoczaszki." },
  { "id": "xr_nasal_bones", "title": "RTG Nasal bones", "group": "Trauma", "section": "Facial bones", "priority": 21,
    "text": "Badanie: RTG kości nosa w projekcji bocznej\n\nOpis:\nKości nosa o zachowanej ciągłości zarysów, bez widocznej linii złamania.\nBez przemieszczenia odłamów kostnych.\nTkanki miękkie grzbietu nosa bez istotnego obrzęku.\n\nWnioski:\n- Bez radiologicznych cech złamania kości nosa." },
  { "id": "xr_mandible", "title": "RTG Mandible", "group": "Trauma", "section": "Facial bones", "priority": 22,
    "text": "Badanie: RTG żuchwy w projekcji PA i projekcjach skośnych\n\nOpis:\nTrzon, kąty i gałęzie żuchwy bez widocznych linii złamań.\nWyrostki kłykciowe i dziobiaste żuchwy bez cech złamania.\nGłowy żuchwy prawidłowo położone w dołach stawowych, bez cech zwichnięcia.\nTkanki miękkie bez istotnych zmian.\n\nWnioski:\n- Bez radiologicznych cech złamania żuchwy.\n- Przy utrzymującym się podejrzeniu klinicznym złamania do rozważenia RTG pantomograficzne lub TK." },
  { "id": "xr_opg", "title": "RTG OPG (pantomogram)", "group": "Non-trauma", "section": "Facial bones", "priority": 23,
    "text": "Badanie: RTG pantomograficzne (OPG)\n\nOpis:\nStan uzębienia: … .\nNie uwidoczniono zmian okołowierzchołkowych ani zmian ogniskowych w wyrostkach zębodołowych szczęki i żuchwy.\nTrzon i gałęzie żuchwy o prawidłowej strukturze kostnej, bez zmian ogniskowych i bez linii złamań.\nKanały żuchwy symetryczne, prawidłowo zarysowane.\nWyrostki kłykciowe i głowy żuchwy symetryczne, prawidłowego kształtu.\nZatoki szczękowe w uwidocznionym zakresie powietrzne, dna zatok gładkie.\n\nWnioski:\n- Obraz pantomograficzny bez istotnych odchyleń od normy." },
  { "id": "xr_sinuses", "title": "RTG Sinuses", "group": "Non-trauma", "section": "Facial bones", "priority": 24,
    "text": "Badanie: RTG zatok przynosowych w projekcji potyliczno-bródkowej\n\nOpis:\nZatoki szczękowe obustronnie prawidłowo powietrzne, bez pogrubienia błony śluzowej i bez poziomów płynu.\nZatoki czołowe prawidłowo powietrzne.\nKomórki sitowe w uwidocznionym zakresie powietrzne.\nŚciany zatok zachowane.\nPrzegroda nosa w przybliżeniu w linii pośrodkowej.\n\nWnioski:\n- Zatoki przynosowe prawidłowo powietrzne." },
  { "id": "xr_neck_soft_tissue_fb", "title": "RTG Soft-tissue neck lateral (foreign body)", "group": "Non-trauma", "section": "Neck", "priority": 20,
    "text": "Badanie: RTG tkanek miękkich szyi w projekcji bocznej – w kierunku ciała obcego\n\nOpis:\nNie uwidoczniono cieniującego ciała obcego w rzucie gardła, krtani ani górnego odcinka przełyku.\nTkanki miękkie przedkręgowe o prawidłowej grubości.\nNie uwidoczniono powietrza w tkankach miękkich przedkręgowych.\nNagłośnia prawidłowego kształtu. Słup powietrza w krtani i tchawicy prawidłowej szerokości.\nZwapnienia chrząstek krtani w typowym położeniu.\n\nW uwidocznionym zakresie kręgosłup szyjny bez istotnych zmian.\n\nWnioski:\n- Nie uwidoczniono cieniującego ciała obcego.\n- Prawidłowy obraz RTG nie wyklucza niecieniującego ciała obcego (np. ości ryby); przy utrzymujących się objawach do rozważenia endoskopia lub TK." },
  { "id": "xr_neck_soft_tissue_child", "title": "RTG Soft-tissue neck child (epiglottitis / croup)", "group": "Non-trauma", "section": "Paediatric", "priority": 40,
    "text": "Badanie: RTG tkanek miękkich szyi u dziecka w projekcji bocznej i AP\n\nOpis:\nNagłośnia prawidłowego kształtu i grubości. Fałdy nalewkowo-nagłośniowe niepogrubiałe.\nSłup powietrza w okolicy podgłośniowej prawidłowej szerokości, bez zwężenia.\nTkanki miękkie zagardłowe o prawidłowej grubości dla wieku.\nNie uwidoczniono cieniującego ciała obcego.\n\nWnioski:\n- Bez radiologicznych cech zapalenia nagłośni ani zwężenia podgłośniowego.\n- Bez cech poszerzenia przestrzeni zagardłowej." },
  { "id": "xr_c_spine_flexion_extension", "title": "RTG C-spine flexion-extension", "group": "Non-trauma", "section": "Spine", "priority": 20,
    "text": "Badanie: RTG kręgosłupa szyjnego w projekcjach czynnościowych bocznych (zgięcie i wyprost)\n\nOpis:\nKręgosłup szyjny uwidoczniony do poziomu C7.\nW zgięciu i w wyproście zachowany płynny zakres ruchomości.\nPrawidłowe ustawienie kręgów w obu pozycjach – bez przemieszczenia trzonów względem siebie i bez patologicznego rozwarcia stawów międzywyrostkowych.\nOdstęp szczytowo-zębowy prawidłowy, również w zgięciu.\nTrzony kręgów o zachowanej wysokości. Przestrzenie międzykręgowe zachowane.\nTkanki miękkie przedkręgowe nieposzerzone.\n\nWnioski:\n- Bez radiologicznych cech niestabilności kręgosłupa szyjnego w badaniu czynnościowym." },
  { "id": "xr_l_spine_flexion_extension", "title": "RTG L-spine flexion-extension", "group": "Non-trauma", "section": "Spine", "priority": 21,
    "text": "Badanie: RTG kręgosłupa lędźwiowego w projekcjach czynnościowych bocznych (zgięcie i wyprost)\n\nOpis:\nPrawidłowe ustawienie trzonów kręgów w zgięciu i w wyproście, bez cech kręgozmyku.\nBez patologicznej ruchomości segmentów – bez przesunięcia trzonów względem siebie i bez nadmiernego kątowego rozwarcia przestrzeni międzykręgowych.\nTrzony kręgów o zachowanej wysokości. Przestrzenie międzykręgowe zachowane.\n\nWnioski:\n- Bez radiologicznych cech niestabilności segmentalnej kręgosłupa lędźwiowego." },
  { "id": "xr_whole_spine_scoliosis", "title": "RTG Whole spine standing (scoliosis)", "group": "Non-trauma", "section": "Spine", "priority": 22,
    "text": "Badanie: RTG całego kręgosłupa na stojąco w projekcjach PA i bocznej\n\nOpis:\nW projekcji PA oś kręgosłupa zachowana, bez istotnego skrzywienia bocznego (kąt Cobba … °).\nBez cech rotacji trzonów kręgów.\nPion z C7 przebiega w linii pośrodkowej kości krzyżowej – zachowany balans w płaszczyźnie czołowej.\nW projekcji bocznej zachowane krzywizny fizjologiczne: lordoza szyjna, kyfoza piersiowa i lordoza lędźwiowa.\nTrzony kręgów prawidłowego kształtu, bez wad rozwojowych.\nMiednica ustawiona poziomo, talerze biodrowe na równej wysokości.\nStopień kostnienia talerzy biodrowych wg Rissera: … .\n\nWnioski:\n- Bez radiologicznych cech skoliozy." },
  { "id": "xr_sacrum_coccyx", "title": "RTG Sacrum/coccyx", "group": "Trauma", "section": "Spine", "priority": 23,
    "text": "Badanie: RTG kości krzyżowej i guzicznej w projekcjach AP i bocznej\n\nOpis:\nKość krzyżowa bez widocznych linii złamań. Łuki otworów krzyżowych zachowane, symetryczne.\nKość guziczna bez cech złamania. Ustawienie kości guzicznej w granicach zmienności osobniczej.\nStawy krzyżowo-biodrowe symetryczne.\nTkanki miękkie bez istotnych zmian.\n\nWnioski:\n- Bez radiologicznych cech złamania kości krzyżowej i guzicznej." },
  { "id": "xr_si_joints", "title": "RTG Sacroiliac joints", "group": "Non-trauma", "section": "Pelvis / Hips", "priority": 20,
    "text": "Badanie: RTG stawów krzyżowo-biodrowych w projekcji AP\n\nOpis:\nSzpary stawów krzyżowo-biodrowych symetryczne, prawidłowej szerokości.\nPowierzchnie stawowe gładkie, ostro zarysowane, bez nadżerek.\nBez sklerotyzacji podchrzęstnej i bez zrostów kostnych.\nUwidocznione fragmenty stawów biodrowych i spojenia łonowego bez istotnych zmian.\n\nWnioski:\n- Bez radiologicznych cech zapalenia stawów krzyżowo-biodrowych.\n- Prawidłowy obraz RTG nie wyklucza wczesnych zmian zapalnych; przy podejrzeniu klinicznym do rozważenia MR stawów krzyżowo-biodrowych." },
  { "id": "xr_shoulder_y_view", "title": "RTG Shoulder AP + Y-view (dislocation)", "group": "Trauma", "section": "Upper limb", "priority": 30,
    "text": "Badanie: RTG stawu barkowego prawego/lewego w projekcji AP i projekcji Y (bocznej łopatki)\n\nOpis:\nW projekcji Y głowa kości ramiennej położona centralnie, na przecięciu ramion litery Y, prawidłowo ustawiona względem panewki stawowej łopatki.\nBez cech zwichnięcia przedniego ani tylnego stawu ramiennego.\nNie uwidoczniono linii złamań w obrębie nasady bliższej kości ramiennej, guzków kości ramiennej, panewki i trzonu łopatki.\nStaw barkowo-obojczykowy prawidłowo ustawiony.\nTkanki miękkie bez zmian.\n\nWnioski:\n- Bez radiologicznych cech zwichnięcia stawu ramiennego.\n- Bez radiologicznych cech świeżego złamania w obrębie obręczy barkowej." },
  { "id": "xr_shoulder_post_reduction", "title": "RTG Shoulder post-reduction", "group": "Trauma", "section": "Upper limb", "priority": 31,
    "text": "Badanie: RTG stawu barkowego prawego/lewego w projekcji AP i projekcji Y – kontrola po nastawieniu zwichnięcia\n\nOpis:\nStan po nastawieniu zwichnięcia stawu ramiennego.\nGłowa kości ramiennej prawidłowo ustawiona względem panewki stawowej łopatki.\nNie uwidoczniono złamania nasady bliższej kości ramiennej ani brzegu panewki.\nBez widocznego wgniecenia na tylno-bocznym obwodzie głowy kości ramiennej.\n\nWnioski:\n- Prawidłowe ustawienie w stawie ramiennym po nastawieniu zwichnięcia.\n- Bez radiologicznych cech towarzyszącego złamania." },
  { "id": "xr_ac_joints", "title": "RTG AC joints", "group": "Trauma", "section": "Upper limb", "priority": 32,
    "text": "Badanie: RTG stawów barkowo-obojczykowych porównawczo obustronnie w projekcji AP\n\nOpis:\nStawy barkowo-obojczykowe prawidłowo ustawione – dolne zarysy wyrostka barkowego i obojczyka na jednej linii obustronnie.\nSzpary stawów barkowo-obojczykowych symetryczne, prawidłowej szerokości.\nOdległości kruczo-obojczykowe symetryczne, prawidłowe.\nBoczne odcinki obojczyków i wyrostki barkowe bez cech złamania.\n\nWnioski:\n- Bez radiologicznych cech uszkodzenia stawów barkowo-obojczykowych." },
  { "id": "xr_scapula", "title": "RTG Scapula", "group": "Trauma", "section": "Upper limb", "priority": 33,
    "text": "Badanie: RTG łopatki prawej/lewej w projekcji AP i projekcji Y\n\nOpis:\nTrzon, szyjka i panewka łopatki bez cech złamania.\nWyrostek barkowy i wyrostek kruczy bez cech złamania.\nStaw ramienny i staw barkowo-obojczykowy prawidłowo ustawione.\nUwidocznione żebra bez cech złamania. W uwidocznionym zakresie bez cech odmy opłucnowej.\n\nWnioski:\n- Bez radiologicznych cech złamania łopatki." },
  { "id": "xr_thumb", "title": "RTG Thumb", "group": "Trauma", "section": "Upper limb", "priority": 34,
    "text": "Badanie: RTG kciuka prawego/lewego w projekcjach AP i bocznej\n\nOpis:\nPaliczki kciuka i I kość śródręcza bez cech złamania, w tym podstawa I kości śródręcza.\nPrawidłowe ustawienie w stawie międzypaliczkowym, śródręczno-paliczkowym oraz nadgarstkowo-śródręcznym I.\nNie uwidoczniono złamania awulsyjnego u podstawy paliczka bliższego.\nSzpary stawowe zachowane.\nTkanki miękkie bez zmian.\n\nWnioski:\n- Bez radiologicznych cech świeżych zmian pourazowych w obrębie kciuka." },
  { "id": "xr_hands_arthritis", "title": "RTG Both hands (arthritis)", "group": "Non-trauma", "section": "Upper limb", "priority": 35,
    "text": "Badanie: RTG obu rąk w projekcji PA (porównawczo)\n\nOpis:\nStruktura kostna prawidłowa, bez osteopenii okołostawowej.\nSzpary stawów międzypaliczkowych, śródręczno-paliczkowych i stawów nadgarstków zachowane, symetryczne.\nNie uwidoczniono nadżerek stawowych ani torbieli podchrzęstnych.\nBez osteofitów i bez sklerotyzacji podchrzęstnej.\nBez zwapnień chrząstek stawowych ani zwapnień w tkankach miękkich.\nPrawidłowe ustawienie w stawach, bez podwichnięć i zniekształceń.\nTkanki miękkie bez zmian.\n\nWnioski:\n- Bez radiologicznych cech zapalnej ani zwyrodnieniowej choroby stawów rąk.\n- Prawidłowy obraz RTG nie wyklucza wczesnego zapalenia stawów; przy podejrzeniu klinicznym do rozważenia USG stawów." },
  { "id": "xr_toes", "title": "RTG Toes", "group": "Trauma", "section": "Lower limb", "priority": 30,
    "text": "Badanie: RTG palców stopy prawej/lewej w projekcjach AP i skośnej\n\nOpis:\nPaliczki palców stopy i głowy kości śródstopia bez cech złamania.\nPrawidłowe ustawienie w stawach śródstopno-paliczkowych i międzypaliczkowych.\nUwidocznione trzeszczki palucha bez cech złamania.\nSzpary stawowe zachowane.\nBez cieniujących ciał obcych w tkankach miękkich.\n\nWnioski:\n- Bez radiologicznych cech świeżych zmian pourazowych w obrębie palców stopy." },
  { "id": "xr_patella_axial", "title": "RTG Patella axial (skyline)", "group": "Trauma", "section": "Lower limb", "priority": 31,
    "text": "Badanie: RTG rzepki prawej/lewej w projekcji osiowej\n\nOpis:\nRzepka bez widocznych linii złamań, o zachowanej ciągłości zarysów.\nRzepka prawidłowo ustawiona w bruździe międzykłykciowej kości udowej, bez cech podwichnięcia bocznego.\nSzpara stawu rzepkowo-udowego zachowana, równomierna.\nBruzda międzykłykciowa kości udowej prawidłowej głębokości.\nTkanki miękkie bez istotnych zmian.\n\nWnioski:\n- Bez radiologicznych cech złamania rzepki.\n- Prawidłowe ustawienie rzepki w stawie rzepkowo-udowym." },
  { "id": "xr_knees_standing", "title": "RTG Knees standing (OA)", "group": "Non-trauma", "section": "Lower limb", "priority": 32,
    "text": "Badanie: RTG obu stawów kolanowych na stojąco (z obciążeniem) w projekcji AP oraz w projekcjach bocznych\n\nOpis:\nSzpary stawowe przedziałów przyśrodkowych i bocznych obu stawów kolanowych zachowane, symetryczne.\nBez osteofitów brzeżnych.\nBez sklerotyzacji podchrzęstnej i bez torbieli podchrzęstnych.\nBez zwapnień chrząstek stawowych i łąkotek.\nOś kończyn w stawach kolanowych prawidłowa.\nStawy rzepkowo-udowe bez istotnych zmian.\nTkanki miękkie bez zmian.\n\nWnioski:\n- Bez radiologicznych cech choroby zwyrodnieniowej stawów kolanowych (Kellgren-Lawrence 0)." },
  { "id": "xr_long_leg_alignment", "title": "RTG Long-leg alignment (standing)", "group": "Non-trauma", "section": "Lower limb", "priority": 33,
    "text": "Badanie: RTG obu kończyn dolnych w całej długości na stojąco w projekcji AP – ocena osi\n\nOpis:\nOś mechaniczna kończyny dolnej prawej i lewej przebiega przez środkową część stawu kolanowego.\nKąt biodrowo-kolanowo-skokowy: po stronie prawej … °, po stronie lewej … °.\nDługość kończyny dolnej prawej … mm, lewej … mm.\nStawy biodrowe, kolanowe i skokowo-goleniowe w zakresie oceny bez istotnych zmian.\n\nWnioski:\n- Prawidłowa oś mechaniczna obu kończyn dolnych.\n- Bez istotnej różnicy długości kończyn dolnych." },
  { "id": "xr_feet_arthritis", "title": "RTG Both feet (arthritis)", "group": "Non-trauma", "section": "Lower limb", "priority": 34,
    "text": "Badanie: RTG obu stóp w projekcjach AP i skośnych (porównawczo)\n\nOpis:\nStruktura kostna prawidłowa, bez osteopenii okołostawowej.\nSzpary stawów śródstopno-paliczkowych, międzypaliczkowych i stawów stępu zachowane, symetryczne.\nNie uwidoczniono nadżerek stawowych, w tym w obrębie głów V kości śródstopia.\nBez osteofitów i bez sklerotyzacji podchrzęstnej.\nPrawidłowe ustawienie palców, bez podwichnięć w stawach śródstopno-paliczkowych.\nTkanki miękkie bez zmian, bez zwapnień.\n\nWnioski:\n- Bez radiologicznych cech zapalnej ani zwyrodnieniowej choroby stawów stóp." },
  { "id": "xr_postop_osteosynthesis", "title": "RTG Post-op control (osteosynthesis)", "group": "Trauma", "section": "Combined", "priority": 30,
    "text": "Badanie: RTG … prawej/lewej w projekcjach AP i bocznej – kontrola po zespoleniu\n\nOpis:\nStan po zespoleniu złamania … przy użyciu … .\nUstawienie odłamów prawidłowe, w osi, bez istotnego przemieszczenia.\nMateriał zespalający prawidłowo położony, ciągły, bez cech obluzowania ani migracji.\nŚruby nie penetrują do jamy stawowej.\nTkanki miękkie bez istotnych zmian.\n\nWnioski:\n- Stan po zespoleniu złamania … – ustawienie odłamów prawidłowe, materiał zespalający w prawidłowym położeniu." },
  { "id": "xr_cast_control", "title": "RTG Cast control", "group": "Trauma", "section": "Combined", "priority": 31,
    "text": "Badanie: RTG … prawej/lewej w opatrunku gipsowym w projekcjach AP i bocznej – kontrola\n\nOpis:\nStan po złamaniu … ; badanie w opatrunku gipsowym (ocena struktury kostnej ograniczona).\nUstawienie odłamów bez zmian w porównaniu z badaniem z dnia … .\nBez wtórnego przemieszczenia odłamów.\nOś kończyny zachowana.\n\nWnioski:\n- Ustawienie odłamów bez wtórnego przemieszczenia w porównaniu z badaniem poprzednim." },
  { "id": "xr_hip_arthroplasty", "title": "RTG Hip arthroplasty control", "group": "Non-trauma", "section": "Pelvis / Hips", "priority": 21,
    "text": "Badanie: RTG stawu biodrowego prawego/lewego w projekcjach AP i osiowej – kontrola po endoprotezoplastyce\n\nOpis:\nStan po endoprotezoplastyce całkowitej stawu biodrowego … .\nGłowa endoprotezy prawidłowo osadzona w panewce, bez cech zwichnięcia.\nPanewka i trzpień endoprotezy prawidłowo ustawione.\nBez poszerzenia przejaśnień na granicy implant–kość i cement–kość – bez cech obluzowania elementów endoprotezy.\nNie uwidoczniono złamania okołoprotezowego.\nBez istotnych skostnień okołostawowych.\n\nWnioski:\n- Endoproteza stawu biodrowego prawidłowo ustawiona, bez radiologicznych cech obluzowania ani złamania okołoprotezowego." },
  { "id": "xr_knee_arthroplasty", "title": "RTG Knee arthroplasty control", "group": "Non-trauma", "section": "Lower limb", "priority": 35,
    "text": "Badanie: RTG stawu kolanowego prawego/lewego w projekcjach AP i bocznej – kontrola po endoprotezoplastyce\n\nOpis:\nStan po endoprotezoplastyce całkowitej stawu kolanowego.\nElementy udowy i piszczelowy endoprotezy prawidłowo ustawione, oś kończyny w stawie kolanowym prawidłowa.\nBez poszerzenia przejaśnień na granicy implant–kość i cement–kość – bez cech obluzowania elementów endoprotezy.\nNie uwidoczniono złamania okołoprotezowego.\nRzepka prawidłowo położona.\n\nWnioski:\n- Endoproteza stawu kolanowego prawidłowo ustawiona, bez radiologicznych cech obluzowania ani złamania okołoprotezowego." },
  { "id": "xr_myeloma_survey", "title": "RTG Skeletal survey (myeloma)", "group": "Non-trauma", "section": "Combined", "priority": 32,
    "text": "Badanie: RTG układu kostnego – przegląd w kierunku szpiczaka (czaszka, kręgosłup, miednica, żebra, kości ramienne i udowe)\n\nOpis:\nNie uwidoczniono zmian osteolitycznych w obrębie kości czaszki, kręgosłupa, miednicy, żeber, kości ramiennych i udowych.\nTrzony kręgów o zachowanej wysokości, bez złamań kompresyjnych.\nBez cech złamań patologicznych.\nStruktura kostna bez cech uogólnionej osteopenii.\n\nWnioski:\n- Bez radiologicznych cech zmian osteolitycznych w badanym zakresie.\n- RTG ma ograniczoną czułość w wykrywaniu zmian szpiczakowych; do rozważenia niskodawkowe TK całego ciała lub MR." },
  { "id": "xr_bone_age", "title": "RTG Bone age (hand)", "group": "Non-trauma", "section": "Paediatric", "priority": 50,
    "text": "Badanie: RTG ręki lewej w projekcji PA – ocena wieku kostnego\n\nOpis:\nWiek kalendarzowy: … lat … mies.\nWiek kostny wg atlasu Greulicha i Pyle: … lat … mies.\nKolejność i stopień kostnienia kości nadgarstka oraz nasad kości ręki prawidłowe.\nStruktura kostna prawidłowa, bez cech dysplazji.\n\nWnioski:\n- Wiek kostny … odpowiada wiekowi kalendarzowemu (w granicach 2 odchyleń standardowych)." },
  { "id": "xr_knee_child", "title": "RTG Knee child", "group": "Trauma", "section": "Paediatric", "priority": 51,
    "text": "Badanie: RTG stawu kolanowego prawego/lewego u dziecka w projekcjach AP i bocznej\n\nOpis:\nJądra kostnienia odpowiednie do wieku, prawidłowo położone.\nChrząstki wzrostowe kości udowej, piszczelowej i strzałkowej prawidłowej szerokości, bez cech przemieszczenia nasad.\nNie uwidoczniono linii złamań, w tym w obrębie wyniosłości międzykłykciowej i guzowatości kości piszczelowej.\nRzepka prawidłowo położona.\nW projekcji bocznej bez cech wysięku w zachyłku nadrzepkowym.\nTkanki miękkie bez zmian.\n\nWnioski:\n- Bez radiologicznych cech świeżych zmian pourazowych w obrębie stawu kolanowego." },
  { "id": "xr_ankle_child", "title": "RTG Ankle child", "group": "Trauma", "section": "Paediatric", "priority": 52,
    "text": "Badanie: RTG stawu skokowo-goleniowego prawego/lewego u dziecka w projekcjach AP i bocznej\n\nOpis:\nJądra kostnienia odpowiednie do wieku.\nChrząstki wzrostowe dalszych nasad kości piszczelowej i strzałkowej prawidłowej szerokości, bez cech przemieszczenia nasad.\nKostki przyśrodkowa i boczna bez cech złamania.\nPrawidłowe ustawienie w stawie skokowo-goleniowym, szpara stawowa równomierna.\nKość skokowa bez cech złamania.\nTkanki miękkie bez istotnych zmian.\n\nWnioski:\n- Bez radiologicznych cech świeżych zmian pourazowych w obrębie stawu skokowo-goleniowego." },
  { "id": "xr_hips_child", "title": "RTG Hips child (Perthes / SCFE)", "group": "Non-trauma", "section": "Paediatric", "priority": 53,
    "text": "Badanie: RTG stawów biodrowych u dziecka w projekcji AP i projekcji Lauensteina\n\nOpis:\nGłowy kości udowych prawidłowo osadzone w panewkach, symetryczne.\nJądra kostnienia głów kości udowych prawidłowej wielkości, wysokości i struktury, bez spłaszczenia, fragmentacji i sklerotyzacji.\nChrząstki wzrostowe bliższych nasad kości udowych symetryczne, prawidłowej szerokości.\nLinia Kleina obustronnie przecina boczną część nasady – bez cech złuszczenia głowy kości udowej.\nSzpary stawowe symetryczne. Linie Shentona zachowane obustronnie.\n\nWnioski:\n- Bez radiologicznych cech choroby Perthesa ani młodzieńczego złuszczenia głowy kości udowej." },
  { "id": "mmg_screening", "title": "MMG Screening mammography (BI-RADS 1)", "group": "Non-trauma", "section": "Chest / Thorax", "priority": 30,
    "text": "Badanie: Mammografia przesiewowa obu piersi w projekcjach CC i MLO\n\nOpis:\nBudowa piersi: kategoria gęstości … wg ACR.\nPiersi symetryczne.\nNie uwidoczniono zmian ogniskowych, zaburzeń architektury ani podejrzanych mikrozwapnień.\nSkóra i brodawki bez zmian.\nW uwidocznionym zakresie dołów pachowych bez powiększonych węzłów chłonnych.\n\nWnioski:\n- Mammografia obu piersi bez zmian – BI-RADS 1.\n- Zalecane kontynuowanie badań przesiewowych zgodnie z programem." },
  { "id": "mmg_diagnostic", "title": "MMG Diagnostic mammography normal", "group": "Non-trauma", "section": "Chest / Thorax", "priority": 31,
    "text": "Badanie: Mammografia diagnostyczna obu piersi w projekcjach CC i MLO\n\nOpis:\nWskazanie: … w piersi … .\nBudowa piersi: kategoria gęstości … wg ACR.\nPiersi symetryczne.\nW miejscu zgłaszanych objawów, oznaczonym znacznikiem, nie uwidoczniono zmiany ogniskowej.\nNie uwidoczniono zmian ogniskowych, zaburzeń architektury ani podejrzanych mikrozwapnień w obu piersiach.\nSkóra i brodawki bez zmian.\nW uwidocznionym zakresie dołów pachowych bez powiększonych węzłów chłonnych.\n\nWnioski:\n- Mammografia obu piersi bez zmian – BI-RADS 1.\n- Przy objawach klinicznych do rozważenia uzupełnienie diagnostyki o USG piersi." },
  { "id": "dxa_normal_tscore", "title": "DXA Densitometry normal (T-score)", "group": "Non-trauma", "section": "Combined", "priority": 40,
    "text": "Badanie: Densytometria metodą DXA – kręgosłup lędźwiowy i bliższy koniec kości udowej\n\nOpis:\nKręgosłup lędźwiowy L1–L4: BMD … g/cm², T-score …, Z-score … .\nSzyjka kości udowej …: BMD … g/cm², T-score …, Z-score … .\nBliższy koniec kości udowej (całkowity) …: BMD … g/cm², T-score …, Z-score … .\nNajniższa wartość T-score: … (…).\nOcena wg kryteriów WHO (kobiety po menopauzie, mężczyźni od 50. roku życia).\n\nWnioski:\n- Gęstość mineralna kości prawidłowa wg kryteriów WHO (T-score ≥ −1,0)." },
  { "id": "dxa_normal_zscore", "title": "DXA Densitometry normal (Z-score)", "group": "Non-trauma", "section": "Combined", "priority": 41,
    "text": "Badanie: Densytometria metodą DXA – kręgosłup lędźwiowy i bliższy koniec kości udowej\n\nOpis:\nKręgosłup lędźwiowy L1–L4: BMD … g/cm², Z-score … .\nSzyjka kości udowej …: BMD … g/cm², Z-score … .\nBliższy koniec kości udowej (całkowity) …: BMD … g/cm², Z-score … .\nOcena na podstawie Z-score (kobiety przed menopauzą, mężczyźni przed 50. rokiem życia).\n\nWnioski:\n- Gęstość mineralna kości w zakresie oczekiwanym dla wieku (Z-score > −2,0)." },
  { "id": "snippet_xr_colles_fracture", "title": "Złamanie Collesa (RTG)", "group": "Snippets", "section": "Trauma snippets", "priority": 30,
    "text": "Złamanie nasady dalszej kości promieniowej … typu Collesa, z grzbietowym przemieszczeniem i kątowym ustawieniem odłamu dalszego (nachylenie powierzchni stawowej … ° grzbietowo), ze skróceniem kości promieniowej o … mm. Szczelina złamania … (nie przechodzi / przechodzi) na powierzchnię stawową. … złamanie wyrostka rylcowatego kości łokciowej." },
  { "id": "snippet_xr_ankle_weber", "title": "Złamanie kostki bocznej Weber … (RTG)", "group": "Snippets", "section": "Trauma snippets", "priority": 31,
    "text": "Złamanie kostki bocznej … typu Weber …, z przemieszczeniem odłamu dalszego o … mm. Przestrzeń przyśrodkowa stawu skokowo-goleniowego … (nieposzerzona / poszerzona do … mm)." },
  { "id": "snippet_xr_supracondylar_child", "title": "Złamanie nadkłykciowe u dziecka (Gartland …)", "group": "Snippets", "section": "Trauma snippets", "priority": 32,
    "text": "Złamanie nadkłykciowe kości ramiennej … typu wyprostnego, Gartland …. Linia przednia kości ramiennej przebiega … główki kości ramiennej. Uniesiona przednia i widoczna tylna poduszeczka tłuszczowa." },
  { "id": "snippet_xr_neck_of_femur_fracture", "title": "Złamanie szyjki kości udowej (Garden …)", "group": "Snippets", "section": "Trauma snippets", "priority": 33,
    "text": "Złamanie szyjki kości udowej … (podgłowowe / przezszyjkowe / podstawy szyjki), Garden …, z … (bez przemieszczenia / przemieszczeniem) odłamów." },
  { "id": "snippet_xr_salter_harris", "title": "Złamanie Salter-Harris … (RTG)", "group": "Snippets", "section": "Trauma snippets", "priority": 34,
    "text": "Złamanie … z zajęciem chrząstki wzrostowej, typ … wg Saltera-Harrisa, z przemieszczeniem nasady o … mm." },
  { "id": "snippet_xr_pneumoperitoneum", "title": "Wolne powietrze pod przeponą (RTG)", "group": "Snippets", "section": "Abdomen snippets", "priority": 30,
    "text": "Pod … kopułą przepony widoczny sierpowaty pas wolnego powietrza o grubości do … mm – obraz odpowiada odmie otrzewnowej." },
  { "id": "snippet_xr_air_fluid_levels", "title": "Poziomy płynowo-gazowe (RTG)", "group": "Snippets", "section": "Abdomen snippets", "priority": 31,
    "text": "W pozycji stojącej liczne poziomy płynowo-gazowe w poszerzonych do … mm pętlach jelita … (cienkiego / grubego), w rzucie … ." },
  { "id": "snippet_xr_osteoarthritis", "title": "Zmiany zwyrodnieniowe stawu (RTG)", "group": "Snippets", "section": "MSK snippets", "priority": 30,
    "text": "Zwężenie szpary stawowej …, osteofity brzeżne i sklerotyzacja podchrzęstna – zmiany zwyrodnieniowe stawu … (Kellgren-Lawrence …)." },
  { "id": "snippet_xr_osteolytic_lesion", "title": "Zmiana osteolityczna (RTG)", "group": "Snippets", "section": "MSK snippets", "priority": 31,
    "text": "W obrębie … widoczna osteolityczna zmiana ogniskowa o wymiarach … × … mm, o … (ostrych, sklerotycznych / nieostrych) granicach, … (bez przerwania / z przerwaniem) warstwy korowej, … (bez odczynu / z odczynem) okostnowym." },
  { "id": "snippet_xr_periosteal_reaction", "title": "Odczyn okostnowy (RTG)", "group": "Snippets", "section": "MSK snippets", "priority": 32,
    "text": "Odczyn okostnowy … (linijny / warstwowy / spikularny, z trójkątem Codmana) wzdłuż … kości … na odcinku ok. … mm." },
  { "id": "snippet_xr_healing_callus", "title": "Kostnina – zrost (RTG)", "group": "Snippets", "section": "MSK snippets", "priority": 33,
    "text": "Wokół szczeliny złamania … widoczna … (wczesna / dojrzała) kostnina; szczelina złamania … (widoczna / częściowo zatarta / niewidoczna) – cechy … (postępującego / pełnego) zrostu kostnego." },
  { "id": "snippet_xr_ett_malposition", "title": "Nieprawidłowe położenie rurki intubacyjnej", "group": "Snippets", "section": "Chest snippets", "priority": 30,
    "text": "Koniec rurki intubacyjnej w … (oskrzelu głównym prawym / ok. … cm powyżej ostrogi tchawicy, na wysokości …) – zalecana korekta położenia rurki o ok. … cm." },
  { "id": "snippet_xr_ng_malposition", "title": "Nieprawidłowe położenie zgłębnika", "group": "Snippets", "section": "Chest snippets", "priority": 31,
    "text": "Zgłębnik … (zwinięty w przełyku / z końcem w przełyku powyżej wpustu / przebiegający do oskrzela … z końcem w rzucie … płuca) – nieprawidłowe położenie zgłębnika; nie należy go używać do karmienia, zalecana korekta położenia." },
];
